const inputItem = $input.first();
const body = inputItem?.json?.body || inputItem?.json || {};

// Validate required fields
if (!body.url) {
  throw new Error("URL missing");
}
if (!body.job_id) {
  throw new Error("job_id missing");
}
if (!body.source_id) {
  throw new Error("source_id missing");
}
if (!body.callback_url) {
  throw new Error("callback_url missing");
}

// Return formatted output array for n8n
return [{
  json: {
    job_id: body.job_id,
    source_id: body.source_id,
    url: body.url,
    callback_url: body.callback_url
  }
}];

// HTTP Request returns the fetched HTML under $json.data.
// Fall back to other common fields just in case.
const data = $json;

let content = "";
if (typeof data.data === "string" && data.data) {
  content = data.data;
} else if (data.article) {
  content = data.article;
} else if (data.main) {
  content = data.main;
} else if (typeof data.body === "string" && data.body) {
  content = data.body;
}

if (!content) {
  throw new Error("No webpage content extracted");
}

// Remove script/style blocks
content = content
  .replace(/<script[\s\S]*?<\/script>/gi, "")
  .replace(/<style[\s\S]*?<\/style>/gi, "")
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, "");

// Remove common unwanted HTML elements
content = content
  .replace(/<nav[\s\S]*?<\/nav>/gi, "")
  .replace(/<footer[\s\S]*?<\/footer>/gi, "")
  .replace(/<aside[\s\S]*?<\/aside>/gi, "");

// Convert common HTML structures into readable text
content = content
  .replace(/<h1[^>]*>/gi, "\n# ")
  .replace(/<h2[^>]*>/gi, "\n## ")
  .replace(/<h3[^>]*>/gi, "\n### ")
  .replace(/<\/h[1-3]>/gi, "\n")
  .replace(/<p[^>]*>/gi, "\n")
  .replace(/<\/p>/gi, "\n")
  .replace(/<li[^>]*>/gi, "\n- ")
  .replace(/<\/li>/gi, "\n");

// Remove remaining HTML tags
content = content.replace(/<[^>]+>/g, " ");

// Decode basic HTML entities
content = content
  .replace(/&nbsp;/gi, " ")
  .replace(/&amp;/gi, "&")
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'");

// Normalize whitespace
content = content
  .replace(/[ \t]+/g, " ")
  .replace(/\n\s*\n+/g, "\n\n")
  .trim();

if (content.length < 200) {
  throw new Error("Extracted content is too short");
}

// Re-attach the job metadata, which the HTTP Request response does not carry.
const meta = $("Code in JavaScript").item.json;

return [
  {
    json: {
      ...meta,
      content
    }
  }
];

const data = $json;

// Extract hostname without the URL global (not available in the Code sandbox).
const hostnameMatch = String(data.url || "").match(/^https?:\/\/([^/?#]+)/i);
const hostname = hostnameMatch ? hostnameMatch[1] : (data.url || "");

const title =
  data.title ||
  data.page_title ||
  hostname;

const content = data.content || "";

const wordCount = content
  .split(/\s+/)
  .filter(Boolean)
  .length;

return [
  {
    json: {
      job_id: data.job_id,
      source_id: data.source_id,

      url: data.url,

      canonical_url: data.canonical_url || data.url,

      title: title,

      domain: hostname,

      language: data.language || "unknown",

      content: content,

      word_count: wordCount,

      character_count: content.length,

      scraped_at: new Date().toISOString(),

      status: "completed"
    }
  }
];
